public class InnerMemoryEpisodicOverrideFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride>
{

    internal InnerMemoryEpisodicOverrideConsolidationConfigurationInputFactory ConsolidationFactory { get; set; }

    internal InnerMemoryEpisodicOverrideExtractionConfigurationInputFactory ExtractionFactory { get; set; }

    internal InnerMemoryEpisodicOverrideReflectionConfigurationInputFactory ReflectionFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride Create()
    {
        var episodicOverrideResult = CreateEpisodicOverride();
        factoryAction?.Invoke(episodicOverrideResult);

        return episodicOverrideResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride CreateEpisodicOverride()
    {
        var episodicOverrideResult = new Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride();

        return episodicOverrideResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.EpisodicOverride result)
    {
        base.CreateChildren(result);

        result.Consolidation ??= ConsolidationFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
        result.Reflection ??= ReflectionFactory?.Build();
    }

} // End Of Class

